import { ShieldCheck, UserPlus, UsersRound } from 'lucide-react';

import { AdminMetric, AdminPage, AdminPageHeader, AdminPanel, adminFieldClass } from '@/features/admin/components';
import { getVendorAccess } from '@/features/vendor/auth/vendorAccess';
import { addVendorTeamMember, updateVendorTeamMember } from '@/features/vendor/team';
import { prisma } from '@/lib/prisma';

export default async function VendorTeamPage(){const access=await getVendorAccess();if(!access.permissions.has('vendor:view'))throw new Error('Vendor access is required.');const members=await prisma.vendorMembership.findMany({where:{vendorId:access.vendor.id},include:{user:{select:{name:true,email:true}}},orderBy:[{role:'asc'},{createdAt:'asc'}]});return <AdminPage><div className="mx-auto max-w-[96rem] space-y-5"><AdminPageHeader eyebrow="Vendor permissions" title="Team Management" description="Vendor members inherit only vendor-scoped permissions. Ownership and workspace approval rights remain protected."/><section className="grid gap-3 sm:grid-cols-3"><AdminMetric icon={UsersRound} label="Members" value={members.length}/><AdminMetric icon={ShieldCheck} label="Active" value={members.filter(item=>item.active).length}/><AdminMetric icon={UserPlus} label="Editors and managers" value={members.filter(item=>['MANAGER','EDITOR'].includes(item.role)).length}/></section>{access.permissions.has('team:manage')?<AdminPanel title="Add team member" description="The person must already have an active Shelsea account."><form action={addVendorTeamMember} className="grid gap-4 sm:grid-cols-[minmax(0,1fr)_12rem_auto]"><input name="email" type="email" required placeholder="member@example.com" className={adminFieldClass}/><select name="role" className={adminFieldClass}><option value="EDITOR">Editor</option><option value="MANAGER">Manager</option><option value="ANALYST">Analyst</option></select><button className="h-11 rounded-full bg-foreground px-5 text-xs font-bold text-background">Add member</button></form></AdminPanel>:null}<AdminPanel title="Current team"><div className="space-y-3">{members.map(member=><article key={member.id} className="flex flex-col gap-4 rounded-3xl border border-border/60 bg-background/55 p-4 sm:flex-row sm:items-center"><div className="min-w-0 flex-1"><p className="truncate text-sm font-black">{member.user.name}</p><p className="truncate text-[10px] text-muted-foreground">{member.user.email}</p></div>{member.role==='OWNER'?<span className="rounded-full bg-primary/10 px-3 py-2 text-[9px] font-black text-primary">OWNER</span>:access.permissions.has('team:manage')?<form action={updateVendorTeamMember} className="flex flex-wrap items-center gap-2"><input type="hidden" name="membershipId" value={member.id}/><select name="role" defaultValue={member.role} className="h-10 rounded-full border border-border bg-background px-3 text-[10px] font-bold"><option value="EDITOR">Editor</option><option value="MANAGER">Manager</option><option value="ANALYST">Analyst</option></select><button name="active" value={member.active?'false':'true'} className="h-10 rounded-full border border-border px-3 text-[10px] font-bold">{member.active?'Deactivate':'Reactivate'}</button></form>:<span className="text-[9px] font-black">{member.role}</span>}</article>)}</div></AdminPanel></div></AdminPage>}
